-- pos-supplier: Flyway baseline (flattened 2026-09-09 from the previous migration history) with the
-- ADR-0062 tenancy schema folded in. Generated by scripts/db/tenancy/flatten.py from a pg_dump of a
-- database migrated with the retired scripts; the tenancy additions are mechanical and are listed in
-- docs/TENANCY_SCHEMA.md. Global (unscoped) tables: src/main/resources/db/tenancy-global-tables.txt.
--
-- Tenant context: app_current_tenant() reads the session setting app.current_tenant, which the
-- TenantAwareDataSource (pos-tenancy-common, plan WS1) binds per checkout. Until then the owner role
-- carries a transitional default (postgres/init-tenancy.sh) and tests set it per connection.
-- With nothing bound: NULL -> every scoped table reads as empty and refuses inserts (fail closed).

-- Functions are emitted before the tables they reference (pg_dump order); do not validate bodies.
SET check_function_bodies = false;

CREATE OR REPLACE FUNCTION public.app_current_tenant() RETURNS uuid
    LANGUAGE sql STABLE PARALLEL SAFE
    AS $$ SELECT NULLIF(current_setting('app.current_tenant', true), '')::uuid $$;

CREATE TABLE public.ext_product_code (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    product_id uuid NOT NULL,
    code_type character varying(16),
    code character varying(64),
    aggregate_version bigint DEFAULT 0 NOT NULL,
    updated_at timestamp(6) with time zone NOT NULL,
    sku character varying(64),
    CONSTRAINT ck_ext_product_code_type CHECK (((code_type IS NULL) OR ((code_type)::text = ANY ((ARRAY['EAN'::character varying, 'UPC'::character varying])::text[]))))
);

CREATE TABLE public.processed_events (
    event_id character varying(36) NOT NULL,
    tenant_id uuid,
    owner character varying(64) NOT NULL,
    processed_at timestamp(6) with time zone NOT NULL
);

CREATE TABLE public.supplier_account (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    id uuid NOT NULL,
    vendor_profile_id uuid NOT NULL,
    role character varying(16) NOT NULL,
    account_number character varying(100) NOT NULL,
    agency_code character varying(50),
    delivery_location_id uuid,
    created_at timestamp(6) with time zone NOT NULL,
    updated_at timestamp(6) with time zone NOT NULL,
    created_by character varying(255),
    updated_by character varying(255),
    version bigint NOT NULL,
    CONSTRAINT chk_saccount_role CHECK (((role)::text = ANY ((ARRAY['BILLING'::character varying, 'DELIVERY'::character varying])::text[]))),
    CONSTRAINT chk_saccount_role_location CHECK (((((role)::text = 'DELIVERY'::text) AND (delivery_location_id IS NOT NULL)) OR (((role)::text = 'BILLING'::text) AND (delivery_location_id IS NULL))))
);

CREATE TABLE public.supplier_audit_access (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    audit_access_id uuid NOT NULL,
    exchange_audit_id uuid NOT NULL,
    vendor_profile_id uuid NOT NULL,
    capability character varying(64) NOT NULL,
    accessed_by character varying(255) NOT NULL,
    accessed_at timestamp(6) with time zone NOT NULL,
    access_kind character varying(32) NOT NULL,
    payload_outcome character varying(32) NOT NULL,
    correlation_id character varying(100),
    CONSTRAINT chk_saccess_kind CHECK (((access_kind)::text = 'PAYLOAD_READ'::text)),
    CONSTRAINT chk_saccess_payload_outcome CHECK (((payload_outcome)::text = ANY ((ARRAY['DECRYPTED'::character varying, 'UNREADABLE'::character varying, 'NOT_CAPTURED'::character varying])::text[])))
);

CREATE TABLE public.supplier_auth_config (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    id uuid NOT NULL,
    vendor_profile_id uuid NOT NULL,
    name character varying(100) NOT NULL,
    type character varying(64) NOT NULL,
    username_ref character varying(512),
    password_ref character varying(512),
    api_key_ref character varying(512),
    api_key_header character varying(100),
    token_url_ref character varying(512),
    client_id_ref character varying(512),
    client_secret_ref character varying(512),
    bearer_token_ref character varying(512),
    created_at timestamp(6) with time zone NOT NULL,
    updated_at timestamp(6) with time zone NOT NULL,
    created_by character varying(255),
    updated_by character varying(255),
    version bigint NOT NULL,
    CONSTRAINT chk_sauth_type CHECK (((type)::text = ANY ((ARRAY['BASIC_PLUS_APIKEY'::character varying, 'OAUTH2_CLIENT_CREDENTIALS'::character varying, 'BEARER'::character varying])::text[])))
);

CREATE TABLE public.supplier_endpoint_binding (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    id uuid NOT NULL,
    vendor_profile_id uuid NOT NULL,
    capability character varying(64) NOT NULL,
    protocol_family character varying(64) NOT NULL,
    protocol_version character varying(64) NOT NULL,
    base_url character varying(1024) NOT NULL,
    path character varying(512) NOT NULL,
    auth_config_name character varying(100) NOT NULL,
    schedule_cron character varying(100),
    enabled boolean NOT NULL,
    capture_level character varying(32),
    created_at timestamp(6) with time zone NOT NULL,
    updated_at timestamp(6) with time zone NOT NULL,
    created_by character varying(255),
    updated_by character varying(255),
    version bigint NOT NULL,
    event_chunk_size integer,
    CONSTRAINT chk_sbinding_capability CHECK (((capability)::text = ANY ((ARRAY['ORDER_CREATE'::character varying, 'ORDER_STATUS'::character varying, 'STOCK_INQUIRY'::character varying, 'STOCK_REPORT'::character varying, 'PRICE_CATALOG'::character varying, 'INVOICE_FETCH'::character varying, 'WORKORDER_AUTHORIZATION'::character varying, 'MARKETING_CATALOG'::character varying, 'TIRE_IDENTIFICATION'::character varying])::text[]))),
    CONSTRAINT chk_sbinding_capture_level CHECK (((capture_level IS NULL) OR ((capture_level)::text = ANY ((ARRAY['FULL'::character varying, 'REDACTED'::character varying, 'METADATA_ONLY'::character varying])::text[])))),
    CONSTRAINT chk_sbinding_family CHECK (((protocol_family)::text = ANY ((ARRAY['EDIWHEEL_A25'::character varying, 'EDIWHEEL_C1'::character varying, 'EDIWHEEL_B'::character varying, 'EDIWHEEL_JSON'::character varying, 'MICHELIN_S2S'::character varying, 'TEST'::character varying])::text[])))
);

CREATE TABLE public.supplier_endpoint_binding_redaction (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    binding_id uuid NOT NULL,
    classification character varying(64) NOT NULL,
    CONSTRAINT chk_sbinding_redaction_classification CHECK (((classification)::text = ANY ((ARRAY['CUSTOMER_IDENTIFIER'::character varying, 'COMMERCIAL_PRICING'::character varying])::text[])))
);

CREATE TABLE public.supplier_event_outbox (
    id uuid NOT NULL,
    topic character varying(255) NOT NULL,
    record_key character varying(255) NOT NULL,
    event_type character varying(128) NOT NULL,
    payload text NOT NULL,
    created_at timestamp(6) with time zone NOT NULL,
    published_at timestamp(6) with time zone,
    attempts integer DEFAULT 0 NOT NULL,
    last_error text
);

CREATE TABLE public.supplier_exchange_audit (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    exchange_audit_id uuid NOT NULL,
    vendor_profile_id uuid NOT NULL,
    supplier_ref character varying(100) NOT NULL,
    binding_id uuid,
    capability character varying(64) NOT NULL,
    protocol_family character varying(64) NOT NULL,
    protocol_version character varying(64) NOT NULL,
    http_method character varying(16) NOT NULL,
    endpoint_uri character varying(2048) NOT NULL,
    attempt integer NOT NULL,
    correlation_id character varying(100) NOT NULL,
    outcome character varying(32) NOT NULL,
    http_status integer,
    started_at timestamp(6) with time zone NOT NULL,
    duration_ms bigint NOT NULL,
    failure_detail character varying(2048),
    capture_level character varying(16) NOT NULL,
    request_payload bytea,
    response_payload bytea,
    payloads_purged_at timestamp(6) with time zone,
    unmapped_fields character varying(4000),
    created_at timestamp(6) with time zone NOT NULL,
    created_by character varying(255),
    CONSTRAINT chk_saudit_attempt CHECK ((attempt >= 1)),
    CONSTRAINT chk_saudit_capture_level CHECK (((capture_level)::text = ANY ((ARRAY['FULL'::character varying, 'REDACTED'::character varying, 'METADATA_ONLY'::character varying])::text[]))),
    CONSTRAINT chk_saudit_duration CHECK ((duration_ms >= 0)),
    CONSTRAINT chk_saudit_metadata_only_has_no_payload CHECK ((((capture_level)::text <> 'METADATA_ONLY'::text) OR ((request_payload IS NULL) AND (response_payload IS NULL)))),
    CONSTRAINT chk_saudit_outcome CHECK (((outcome)::text = ANY ((ARRAY['OK'::character varying, 'PRE_SEND_FAILURE'::character varying, 'POST_SEND_AMBIGUOUS'::character varying, 'DEFINITIVE_REJECTION'::character varying, 'CONFIGURATION_ERROR'::character varying])::text[])))
);

CREATE TABLE public.supplier_invoice (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    supplier_invoice_id uuid NOT NULL,
    vendor_profile_id uuid NOT NULL,
    supplier_ref character varying(100) NOT NULL,
    vendor_invoice_number character varying(70) NOT NULL,
    invoice_date date NOT NULL,
    invoice_type character varying(16) NOT NULL,
    currency character varying(3) NOT NULL,
    total_net_amount numeric(19,4),
    total_tax_amount numeric(19,4),
    total_gross_amount numeric(19,4),
    vendor_order_reference character varying(70),
    fetched_at timestamp(6) with time zone NOT NULL,
    created_at timestamp(6) with time zone NOT NULL,
    updated_at timestamp(6) with time zone NOT NULL,
    CONSTRAINT supplier_invoice_type_check CHECK (((invoice_type)::text = ANY ((ARRAY['INVOICE'::character varying, 'CREDIT_NOTE'::character varying])::text[])))
);

CREATE TABLE public.supplier_invoice_line (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    supplier_invoice_line_id uuid NOT NULL,
    supplier_invoice_id uuid NOT NULL,
    line_number integer NOT NULL,
    article_ean character varying(64),
    supplier_article_code character varying(64),
    quantity integer,
    unit_price numeric(19,4),
    line_amount numeric(19,4),
    vendor_order_reference character varying(70),
    created_at timestamp(6) with time zone NOT NULL
);

CREATE TABLE public.supplier_mktcat_subscription (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    supplier_mktcat_subscription_id uuid NOT NULL,
    vendor_profile_id uuid NOT NULL,
    supplier_ref character varying(100) NOT NULL,
    event_name character varying(100) NOT NULL,
    callback_url character varying(1000) NOT NULL,
    status character varying(20) NOT NULL,
    failure_detail character varying(1000),
    subscribed_at timestamp(6) with time zone,
    last_callback_at timestamp(6) with time zone,
    created_at timestamp(6) with time zone NOT NULL,
    updated_at timestamp(6) with time zone NOT NULL,
    CONSTRAINT ck_mktcat_sub_status CHECK (((status)::text = ANY ((ARRAY['ACTIVE'::character varying, 'FAILED'::character varying, 'CANCELLED'::character varying])::text[])))
);

CREATE TABLE public.supplier_mktcat_variant (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    supplier_mktcat_variant_id uuid NOT NULL,
    vendor_profile_id uuid NOT NULL,
    supplier_ref character varying(100) NOT NULL,
    vendor_variant_id character varying(100) NOT NULL,
    brand character varying(200),
    tread_design character varying(200),
    tread_design_2 character varying(200),
    product_name character varying(300),
    vehicle_type character varying(100),
    seasonality character varying(100),
    content_hash character varying(64) NOT NULL,
    texts_json text NOT NULL,
    images_json text NOT NULL,
    has_unresolved_images boolean DEFAULT false NOT NULL,
    first_seen_at timestamp(6) with time zone NOT NULL,
    last_seen_at timestamp(6) with time zone NOT NULL,
    last_published_at timestamp(6) with time zone,
    created_at timestamp(6) with time zone NOT NULL,
    updated_at timestamp(6) with time zone NOT NULL
);

CREATE TABLE public.supplier_pricat_entry (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    entry_id uuid NOT NULL,
    import_manifest_id uuid NOT NULL,
    vendor_profile_id uuid NOT NULL,
    position_number integer,
    article_ean character varying(64),
    supplier_article_code character varying(64),
    x_reference_code character varying(64),
    matched_product_id uuid,
    match_method character varying(32) NOT NULL,
    suggested_retail_price numeric(19,4),
    gross_price numeric(19,4),
    net_price numeric(19,4),
    tax_rate numeric(9,4),
    recycling_fee numeric(19,4),
    effective_from date NOT NULL,
    buyer_account_number character varying(64) NOT NULL,
    country_code character varying(8) NOT NULL,
    currency character varying(8) NOT NULL,
    source_document_id character varying(255),
    source_document_date date,
    fetched_at timestamp(6) with time zone NOT NULL,
    created_at timestamp(6) with time zone NOT NULL,
    chunk_sequence integer NOT NULL,
    CONSTRAINT ck_spricat_entry_match_method CHECK (((match_method)::text = ANY ((ARRAY['EAN'::character varying, 'UPC_XREFERENCE'::character varying, 'UNMATCHED'::character varying])::text[])))
);

COMMENT ON COLUMN public.supplier_pricat_entry.chunk_sequence IS 'The 1-based chunk event this line was published in. Fixed at staging so a re-emit reproduces the original chunk boundaries the consumer deduplicates on.';

CREATE TABLE public.supplier_pricat_import (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    import_manifest_id uuid NOT NULL,
    vendor_profile_id uuid NOT NULL,
    supplier_ref character varying(100) NOT NULL,
    protocol_family character varying(64) NOT NULL,
    protocol_version character varying(64) NOT NULL,
    status character varying(32) NOT NULL,
    source_document_id character varying(255),
    source_document_date date,
    buyer_account_number character varying(64) NOT NULL,
    buyer_agency_code character varying(16),
    country_code character varying(8),
    currency character varying(8),
    fetched_at timestamp(6) with time zone NOT NULL,
    completed_at timestamp(6) with time zone,
    lines_fetched integer DEFAULT 0 NOT NULL,
    lines_matched integer DEFAULT 0 NOT NULL,
    lines_unmatched integer DEFAULT 0 NOT NULL,
    lines_duplicate integer DEFAULT 0 NOT NULL,
    chunk_count integer DEFAULT 0 NOT NULL,
    chunk_size integer DEFAULT 0 NOT NULL,
    content_checksum character varying(64),
    exchange_audit_id uuid,
    correlation_id character varying(100) NOT NULL,
    failure_detail character varying(2000),
    created_at timestamp(6) with time zone NOT NULL,
    created_by character varying(100),
    reapplied_from_import_id uuid,
    republish_count integer DEFAULT 0 NOT NULL,
    last_republished_at timestamp(6) with time zone,
    binding_id uuid,
    window_from timestamp(6) with time zone,
    window_to timestamp(6) with time zone,
    checkpoint_state text,
    checkpoint_at timestamp(6) with time zone,
    error_code character varying(64),
    CONSTRAINT ck_spricat_import_counts CHECK (((lines_fetched >= 0) AND (lines_matched >= 0) AND (lines_unmatched >= 0) AND (lines_duplicate >= 0))),
    CONSTRAINT ck_spricat_import_error_code CHECK (((error_code IS NULL) OR ((error_code)::text = ANY ((ARRAY['FETCH_FAILED'::character varying, 'DECODE_FAILED'::character varying])::text[])))),
    CONSTRAINT ck_spricat_import_status CHECK (((status)::text = ANY ((ARRAY['IN_PROGRESS'::character varying, 'COMPLETED'::character varying, 'EMPTY'::character varying, 'FAILED'::character varying])::text[])))
);

COMMENT ON COLUMN public.supplier_pricat_import.reapplied_from_import_id IS 'Set when this manifest re-applied quarantined lines of an earlier import (#1310); null for a vendor fetch.';

COMMENT ON COLUMN public.supplier_pricat_import.republish_count IS 'How many times this import has been re-emitted on consumer request; bounded by pos.supplier.pricat.republish-max-attempts.';

CREATE TABLE public.supplier_pricat_unmatched_line (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    unmatched_line_id uuid NOT NULL,
    import_manifest_id uuid NOT NULL,
    vendor_profile_id uuid NOT NULL,
    position_number integer,
    article_ean character varying(64),
    supplier_article_code character varying(64),
    x_reference_code character varying(64),
    reason character varying(48) NOT NULL,
    reason_detail character varying(1000),
    suggested_retail_price numeric(19,4),
    gross_price numeric(19,4),
    net_price numeric(19,4),
    tax_rate numeric(9,4),
    recycling_fee numeric(19,4),
    effective_from date,
    buyer_account_number character varying(64) NOT NULL,
    country_code character varying(8),
    currency character varying(8),
    source_document_id character varying(255),
    source_document_date date,
    fetched_at timestamp(6) with time zone NOT NULL,
    resolved_at timestamp(6) with time zone,
    resolved_product_id uuid,
    created_at timestamp(6) with time zone NOT NULL,
    CONSTRAINT ck_spricat_unmatched_reason CHECK (((reason)::text = ANY ((ARRAY['NO_IDENTIFIER'::character varying, 'NO_CATALOG_MATCH'::character varying, 'AMBIGUOUS_CATALOG_MATCH'::character varying, 'CATALOG_UNAVAILABLE'::character varying, 'DUPLICATE_LINE'::character varying, 'MALFORMED_LINE'::character varying])::text[])))
);

CREATE TABLE public.supplier_profile (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    vendor_profile_id uuid NOT NULL,
    supplier_ref character varying(100) NOT NULL,
    display_name character varying(255) NOT NULL,
    enabled boolean NOT NULL,
    sandbox boolean DEFAULT false NOT NULL,
    sandbox_base_url_override character varying(1024),
    connect_timeout_ms integer,
    read_timeout_ms integer,
    retry_max_attempts integer,
    retry_backoff character varying(32),
    source_of_truth character varying(16) NOT NULL,
    created_at timestamp(6) with time zone NOT NULL,
    updated_at timestamp(6) with time zone NOT NULL,
    created_by character varying(255),
    updated_by character varying(255),
    version bigint NOT NULL,
    CONSTRAINT chk_sprofile_connect_timeout CHECK (((connect_timeout_ms IS NULL) OR (connect_timeout_ms > 0))),
    CONSTRAINT chk_sprofile_read_timeout CHECK (((read_timeout_ms IS NULL) OR (read_timeout_ms > 0))),
    CONSTRAINT chk_sprofile_retry_backoff CHECK (((retry_backoff IS NULL) OR ((retry_backoff)::text = ANY ((ARRAY['FIXED'::character varying, 'EXPONENTIAL'::character varying])::text[])))),
    CONSTRAINT chk_sprofile_retry_max CHECK (((retry_max_attempts IS NULL) OR (retry_max_attempts >= 0))),
    CONSTRAINT chk_sprofile_source_of_truth CHECK (((source_of_truth)::text = ANY ((ARRAY['YAML'::character varying, 'ADMIN'::character varying])::text[])))
);

CREATE TABLE public.supplier_schedule_lease (
