    created_at timestamp(6) with time zone NOT NULL,
    created_by character varying(100),
    CONSTRAINT ck_sstock_snapshot_status CHECK (((status)::text = ANY ((ARRAY['COMPLETED'::character varying, 'EMPTY'::character varying, 'REJECTED'::character varying, 'FAILED'::character varying])::text[])))
);

CREATE TABLE public.supplier_stock_snapshot_line (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    line_id uuid NOT NULL,
    snapshot_id uuid NOT NULL,
