    CONSTRAINT ck_stintent_intent_type CHECK (((intent_type)::text = ANY ((ARRAY['INITIAL'::character varying, 'REVISION'::character varying, 'REPLACEMENT'::character varying, 'SPLIT'::character varying])::text[]))),
    CONSTRAINT ck_stintent_revision CHECK ((revision >= 0))
