    poll_location character varying(1000),
    contract_reference character varying(100),
    authorized_amount numeric(19,4),
    currency character varying(3),
    reason_code character varying(50),
    reason_text character varying(1000),
    review_reason character varying(1000),
    approval_status character varying(20) DEFAULT 'NOT_REQUESTED'::character varying NOT NULL,
    approval_attempts integer DEFAULT 0 NOT NULL,
    approved_at timestamp(6) with time zone,
    requested_at timestamp(6) with time zone NOT NULL,
