    CONSTRAINT ck_swa_approval_status CHECK (((approval_status)::text = ANY ((ARRAY['NOT_REQUESTED'::character varying, 'PENDING'::character varying, 'APPROVED'::character varying, 'MANUAL_REVIEW'::character varying])::text[]))),
